	}
	name = rcu_dereference(kntmp->name);
	dtmp = lookup_positive_unlocked(name, dentry, strlen(name));
	dput(dentry);
	if (IS_ERR(dtmp))
		return dtmp;
	knparent = kntmp;
	dentry = dtmp;
} while (true);

